import React, { useState } from "react";
import Background from "../components/Background";
import FilterBar from "../components/FilterBar";
import ProjectCard from "../components/ProjectCard";
import ProjectModal from "../components/ProjectModal";
import projectsData from "../data/projectsData";
import "../styles/Marketplace.css";

const Marketplace = () => {
  const [selectedProject, setSelectedProject] = useState(null);
  const [filters, setFilters] = useState({ type: "Tất cả", location: "Tất cả" });

  const filteredProjects = projectsData.filter(
    (p) =>
      (filters.type === "Tất cả" || p.type === filters.type) &&
      (filters.location === "Tất cả" || p.location.includes(filters.location))
  );

  return (
    <Background showShapes={false} fullWidth={true}>
      <div className="marketplace-container">
        {/* Hero Section */}
        <section className="marketplace-hero">
          <div className="hero-overlay" />
          <div className="hero-content">
            <h1>Dự Án Bất Động Sản Cao Cấp</h1>
            <p>
              Khám phá hơn <b>{projectsData.length}</b> dự án nổi bật — từ căn hộ,
              biệt thự đến khu nghỉ dưỡng trên toàn Việt Nam.
            </p>
          </div>
        </section>

        {/* Bộ lọc */}
        <FilterBar filters={filters} setFilters={setFilters} />

        {/* Danh sách dự án */}
        <div className="projects-grid">
          {filteredProjects.map((project) => (
            <ProjectCard
              key={project.id}
              project={project}
              onSelect={() => setSelectedProject(project)}
            />
          ))}
        </div>

        {/* Modal chi tiết */}
        {selectedProject && (
          <ProjectModal
            project={selectedProject}
            onClose={() => setSelectedProject(null)}
          />
        )}
      </div>
    </Background>
  );
};

export default Marketplace;
